import {themes as prismThemes} from 'prism-react-renderer';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import fs from 'node:fs';
import type {Config} from '@docusaurus/types';
import type * as Preset from '@docusaurus/preset-classic';
import type {VersionOptions} from '@docusaurus/plugin-content-docs';

// Docs live in ../docs as plain Markdown. The API reference under
// docs/reference/ts_shape is generated by `python scripts/gen_ref_pages.py`,
// which must run before `npm run build` / `npm start`.

const repo = 'https://github.com/ts-shape/ts-shape';

// Docs versions: `python .github/scripts/docs_versions.py` (release CI)
// snapshots the newest release of each minor line into versioned_docs/ and
// writes versions.json (newest first) and versions-meta.json (labels). The
// newest release is served at the root, older lines at /X.Y/ and unreleased
// main at /next/. Without these files (pull requests, local builds) the site
// is unversioned. DOCS_PATH / SIDEBARS_PATH let the script snapshot a tag.
function readJson<T>(file: string, fallback: T): T {
  try {
    return JSON.parse(fs.readFileSync(new URL(file, import.meta.url), 'utf8')) as T;
  } catch {
    return fallback;
  }
}
const releasedVersions = readJson<string[]>('./versions.json', []);
const versionMeta = readJson<Record<string, {label: string; tag: string}>>(
  './versions-meta.json',
  {},
);
const latestVersion = releasedVersions[0];
const versioned = latestVersion !== undefined;
const versionOptions: Record<string, VersionOptions> = Object.fromEntries([
  ['current', {label: 'Next (unreleased)', path: 'next', banner: 'unreleased'}],
  ...releasedVersions.map((name) => [
    name,
    {
      label: versionMeta[name]?.label ?? name,
      banner: name === latestVersion ? 'none' : 'unmaintained',
    },
  ]),
]);

const config: Config = {
  title: 'ts-shape',
  tagline:
    'Manufacturing time-series analytics for pandas: events, KPIs, SPC and event logs from long-format signal data.',
  favicon: 'img/favicon-32x32.png',

  url: 'https://ts-shape.github.io',
  baseUrl: '/ts-shape/',
  organizationName: 'ts-shape',
  projectName: 'ts-shape',
  trailingSlash: true,

  // The equivalent of `mkdocs build --strict`.
  onBrokenLinks: 'throw',
  onBrokenAnchors: 'throw',
  onDuplicateRoutes: 'throw',

  // Rspack + SWC instead of webpack + Babel.
  future: {
    faster: true,
    // Required by faster.ssgWorkerThreads. The other v4 flags stay off; CSS
    // cascade layers would change the precedence of src/css/custom.css.
    v4: {
      removeLegacyPostBuildHeadAttribute: true,
    },
  },

  markdown: {
    // .md files are CommonMark, not MDX: braces and `<` in prose and
    // docstrings are text, not JSX.
    format: 'detect',
    // ```mermaid fences render as diagrams.
    mermaid: true,
    hooks: {
      onBrokenMarkdownLinks: 'throw',
    },
  },

  i18n: {
    defaultLocale: 'en',
    locales: ['en'],
  },

  presets: [
    [
      'classic',
      {
        docs: {
          path: process.env.DOCS_PATH ?? '../docs',
          routeBasePath: '/',
          sidebarPath: process.env.SIDEBARS_PATH ?? './sidebars.ts',
          // Unreleased docs are edited on main; a released version links to
          // its source at the release tag.
          editUrl: ({version, docPath}) =>
            version === 'current'
              ? `${repo}/edit/main/docs/${docPath}`
              : `${repo}/blob/${versionMeta[version]?.tag ?? 'main'}/docs/${docPath}`,
          ...(versioned ? {lastVersion: latestVersion, versions: versionOptions} : {}),
          exclude: ['assets/**'],
          showLastUpdateTime: true,
          // Tags are declared in docs/tags.yml; an unknown tag fails the build.
          tags: 'tags.yml',
          onInlineTags: 'throw',
          // Only $$...$$ is math: "$input" in the pipeline docs and the
          // changelog stays text.
          remarkPlugins: [[remarkMath, {singleDollarTextMath: false}]],
          rehypePlugins: [rehypeKatex],
        },
        blog: false,
        theme: {
          customCss: './src/css/custom.css',
        },
      } satisfies Preset.Options,
    ],
  ],

  themes: [
    '@docusaurus/theme-mermaid',
    [
      '@easyops-cn/docusaurus-search-local',
      {
        hashed: true,
        indexBlog: false,
        docsDir: '../docs',
        docsRouteBasePath: '/',
        highlightSearchTermsOnTargetPage: true,
      },
    ],
  ],

  plugins: [
    [
      '@docusaurus/plugin-client-redirects',
      {
        // The only URL of the former MkDocs site that no longer exists
        // (checked by comparing both builds' pages).
        redirects: [{from: '/reference/SUMMARY', to: '/reference/'}],
      },
    ],
    [
      'docusaurus-plugin-llms',
      {
        // llms.txt (an index of every page) and llms-full.txt (all pages,
        // the API reference included) for AI coding assistants; with
        // versions, the newest release (served at the root).
        docsDir: versioned ? `versioned_docs/version-${latestVersion}` : '../docs',
        title: 'ts-shape',
        description:
          'Manufacturing time-series analytics for pandas: events, KPIs, SPC and event logs from long-format signal data.',
        ignoreFiles: ['changelog.md', 'license.md', 'insiders/**', 'assets/**'],
        includeOrder: [
          'index.md',
          'user_guide/**',
          'concept.md',
          'naming.md',
          'guides/**',
          'modules/**',
          'reference/**',
        ],
        includeUnmatchedLast: true,
        excludeImports: true,
        removeDuplicateHeadings: true,
      },
    ],
  ],

  themeConfig: {
    image: 'img/social-card.png',
    colorMode: {
      respectPrefersColorScheme: true,
    },
    docs: {
      sidebar: {
        hideable: true,
        autoCollapseCategories: true,
      },
    },
    navbar: {
      hideOnScroll: true,
      logo: {
        alt: 'ts-shape',
        src: 'img/logo-light.png',
        srcDark: 'img/logo-dark.png',
        width: 114,
        height: 32,
      },
      items: [
        {type: 'docSidebar', sidebarId: 'getStarted', position: 'left', label: 'Get started'},
        {type: 'docSidebar', sidebarId: 'concepts', position: 'left', label: 'Concepts'},
        {type: 'docSidebar', sidebarId: 'guides', position: 'left', label: 'Guides'},
        {type: 'docSidebar', sidebarId: 'modules', position: 'left', label: 'Modules'},
        {type: 'docSidebar', sidebarId: 'api', position: 'left', label: 'API'},
        {type: 'docSidebar', sidebarId: 'project', position: 'left', label: 'Project'},
        ...(versioned
          ? [
              {
                type: 'docsVersionDropdown' as const,
                position: 'right' as const,
                dropdownItemsAfter: [{to: '/changelog/', label: 'Changelog'}],
              },
            ]
          : []),
        {
          href: repo,
          position: 'right',
          className: 'header-github-link',
          'aria-label': 'GitHub repository',
        },
      ],
    },
    footer: {
      style: 'dark',
      links: [
        {
          title: 'Docs',
          items: [
            {label: 'Overview', to: '/overview/'},
            {label: 'Quick start', to: '/user_guide/quick_start/'},
            {label: 'Module reference', to: '/modules/'},
            {label: 'API reference', to: '/reference/'},
          ],
        },
        {
          title: 'Project',
          items: [
            {label: 'Changelog', to: '/changelog/'},
            {label: 'Migration and deprecations', to: '/migration/'},
            {label: 'Contributing', to: '/contributing/'},
            {label: 'Topics and standards', to: '/tags/'},
          ],
        },
        {
          title: 'Links',
          items: [
            {label: 'GitHub', href: repo},
            {label: 'PyPI', href: 'https://pypi.org/project/ts-shape/'},
            {label: 'llms.txt', href: 'pathname:///llms.txt'},
          ],
        },
      ],
      copyright: `Copyright © 2024-${new Date().getFullYear()} Jakob Gabriel`,
    },
    tableOfContents: {
      minHeadingLevel: 2,
      maxHeadingLevel: 3,
    },
    mermaid: {
      theme: {light: 'neutral', dark: 'dark'},
      options: {
        fontFamily: 'Inter Variable, system-ui, sans-serif',
        flowchart: {curve: 'basis', padding: 12, wrappingWidth: 320},
      },
    },
    prism: {
      theme: prismThemes.oneLight,
      darkTheme: prismThemes.oneDark,
      additionalLanguages: ['python', 'bash', 'yaml', 'toml', 'json'],
    },
  } satisfies Preset.ThemeConfig,
};

export default config;
